// CSD_RATIONALE_BEGIN
// Best result (attempt 43): 52%/99%. Primary failure: 141/300 semantic mismatches —
// the model generates syntactically valid SQL but with hallucinated table/column names
// not present in the schema. The constraint (GroupBoostedConstrainedStep) ensures SQL
// grammar validity, but cannot prevent identifier hallucination within the grammar.
//
// This attempt replaces the manual Phase 3 generation loop with
// RegenerateUnitOnGroundingFailure, which is specifically designed for this failure mode:
// it tracks schema-symbol boundaries (table names, column names), checks whether each
// completed identifier is grounded in the visible prompt context (schema + question),
// and resamples with penalty when an ungrounded identifier is detected — exactly the
// correction needed for the spider dataset.
//
// Structure (unchanged from best attempt except Phase 3):
//   Phase 1: Up to 5 unconstrained preamble steps (emit "SQL: " prefix).
//   Phase 2: Force "<<" open if model did not emit it naturally.
//   Phase 3: RegenerateUnitOnGroundingFailure with budget = min(850, remaining−1)
//             and maxRetries=3; reserved 1 step for Phase 4.
//   Phase 4: CloseSpanWithinBudget(min(80, remaining)) as fallback close.
//
// Guidance: same schema-only emphasis as best attempt (no invented names).
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Guard includes !insideConstrainedOut, so the flag flips true only
//   when RenderedEndsWith fires; we set currentConstrainedOut := [] which is valid by
//   the method precondition parser.IsValidPrefix([]). EOS keeps the flag false (vacuous).
//
// Phase 2 OpenConstrainedSpan: Only runs when !insideConstrainedOut. Helper sets
//   currentConstrainedOut := []; IsValidPrefix([]) holds by precondition. ✓
//
// Phase 3 RegenerateUnitOnGroundingFailure: Postcondition guarantees
//   parser.IsValidPrefix(resultConstrained). We assign currentConstrainedOut :=
//   resultConstrained, so the invariant is directly satisfied. insideConstrainedOut
//   remains true (the helper does not close the span), making the implication active;
//   it holds because resultConstrained is parser-valid by postcondition. ✓
//
// Phase 4 CloseSpanWithinBudget: Postcondition guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
// Invariant 2: progress
//   |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep increments steps by 1 and appends at most 1 visible token
//   (0 on EOS, 1 otherwise). Each iteration preserves the invariant.
//
// Phase 2: OpenConstrainedSpan increments steps by 1 and appends exactly 1 "<<" token.
//   Net 1:1, invariant preserved.
//
// Phase 3: RegenerateUnitOnGroundingFailure costs at most genBudget token-steps;
//   by postcondition |resultConstrained| <= |currentConstrainedOut_before| + genBudget.
//   new |generated| = stableLen + |resultConstrained|
//     = (|generated_before| − C) + |resultConstrained|
//     ≤ (|generated_before| − C) + C + genBudget
//     = |generated_before| + genBudget
//     ≤ |generatedPrefix| + steps_before + genBudget
//     = |generatedPrefix| + steps_after. ✓
//   steps_after = steps_before + genBudget ≤ maxSteps − 1 (since genBudget ≤ budget3 − 1
//   and budget3 ≤ maxSteps − steps_before), so at least 1 step remains for Phase 4. ✓
//
// Phase 4: CloseSpanWithinBudget postcondition |generatedOut| ≤ |generated| + budget.
//   steps grows by closeBudget ≤ remaining = maxSteps − steps_before_phase4.
//   So steps_after ≤ maxSteps. ✓  cost = steps ≤ maxSteps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a complete SQL SELECT statement using ONLY the exact table and column names from the schema. No invented names, no aliases not in the schema.");

var steps: nat := 0;

// Phase 1: Short preamble – let model emit "SQL: " naturally (at most 5 steps)
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force open span if model did not emit "<<" naturally
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Grounded constrained SQL generation via RegenerateUnitOnGroundingFailure.
// This helper generates SQL unit-by-unit, rolling back and resampling any unit whose
// identifier tokens are not grounded in the visible prompt (schema + question), directly
// targeting the identifier-hallucination root cause of 141/300 semantic mismatches.
if insideConstrainedOut && steps < maxSteps {
  var stableLen := |generated| - |currentConstrainedOut|;
  var stablePrefix3 := generated[..stableLen];
  var budget3 := maxSteps - steps;
  if budget3 > 850 { budget3 := 850; }
  // Reserve at least 1 step for Phase 4 close
  var genBudget: nat := if budget3 > 1 then budget3 - 1 else 0;
  if genBudget > 0 {
    var maxRollback: nat := if genBudget / 5 > 0 then genBudget / 5 else 1;
    var resultConstrained := helpers.RegenerateUnitOnGroundingFailure(
      lm, parser, stablePrefix3, currentConstrainedOut, eosToken, genBudget, 3, maxRollback
    );
    currentConstrainedOut := resultConstrained;
    generated := stablePrefix3 + resultConstrained;
    steps := steps + genBudget;
  }
}

// Phase 4: Close the span if still open – use CloseSpanWithinBudget as fallback
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat := if remaining <= 80 then remaining else 80;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

